package solution

import (
	"reflect"
	"testing"
)

func TestReconcileMalformedBlueprint(t *testing.T) {
	tests := []Blueprint{
		{Labels: map[string]string{"x": "y"}},
		{Name: "x", Labels: map[string]string{"": "y"}},
	}

	for _, bp := range tests {
		result, err := Reconcile(bp, nil)
		if err == nil {
			t.Fatalf("Reconcile(%+v, nil) returned nil error", bp)
		}
		if result.Action != "error" {
			t.Fatalf("Reconcile(%+v, nil) action = %q, want error", bp, result.Action)
		}
		want := []Condition{{Type: "Invalid", Active: true}}
		if !reflect.DeepEqual(result.Conditions, want) {
			t.Fatalf("Reconcile(%+v, nil) conditions = %+v, want %+v", bp, result.Conditions, want)
		}
	}
}

func TestReconcileCreate(t *testing.T) {
	blueprint := Blueprint{Name: "desired", Labels: map[string]string{"app": "x"}}
	result, err := Reconcile(blueprint, nil)
	if err != nil {
		t.Fatalf("Reconcile() error = %v", err)
	}
	if result.Action != "create" || result.Workload == nil {
		t.Fatalf("result = %+v, want create with workload", result)
	}
	if result.Workload.Name != blueprint.Name || !reflect.DeepEqual(result.Workload.Labels, blueprint.Labels) {
		t.Fatalf("workload = %+v, want blueprint name and labels", result.Workload)
	}
	wantConditions := []Condition{{Type: "Provisioning", Active: true}}
	if !reflect.DeepEqual(result.Conditions, wantConditions) {
		t.Fatalf("conditions = %+v, want %+v", result.Conditions, wantConditions)
	}

	result.Workload.Labels["app"] = "changed"
	if blueprint.Labels["app"] != "x" {
		t.Fatal("created workload aliases blueprint labels")
	}
}

func TestReconcileDelete(t *testing.T) {
	blueprint := Blueprint{Name: "desired", Labels: map[string]string{"app": "x"}}
	current := &Workload{
		Name:       "old",
		Labels:     map[string]string{"lifecycle": "remove", "x": "y"},
		Conditions: []Condition{{Type: "Ready", Active: true}},
	}
	before := Workload{
		Name:       current.Name,
		Labels:     map[string]string{"lifecycle": "remove", "x": "y"},
		Conditions: append([]Condition(nil), current.Conditions...),
	}

	result, err := Reconcile(blueprint, current)
	if err != nil {
		t.Fatalf("Reconcile() error = %v", err)
	}
	if result.Action != "delete" || result.Workload != nil {
		t.Fatalf("result = %+v, want delete with nil workload", result)
	}
	wantConditions := []Condition{{Type: "Removing", Active: true}}
	if !reflect.DeepEqual(result.Conditions, wantConditions) {
		t.Fatalf("conditions = %+v, want %+v", result.Conditions, wantConditions)
	}
	if !reflect.DeepEqual(*current, before) {
		t.Fatalf("current mutated: got %+v, want %+v", *current, before)
	}
}

func TestReconcileUpdate(t *testing.T) {
	tests := []struct {
		name    string
		current *Workload
	}{
		{
			name: "name differs",
			current: &Workload{
				Name:       "old",
				Labels:     map[string]string{"app": "x"},
				Conditions: []Condition{{Type: "Old", Active: true}},
			},
		},
		{
			name: "label value differs",
			current: &Workload{
				Name:   "desired",
				Labels: map[string]string{"app": "old"},
			},
		},
		{
			name: "extra label differs",
			current: &Workload{
				Name:   "desired",
				Labels: map[string]string{"app": "x", "extra": "value"},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			blueprint := Blueprint{Name: "desired", Labels: map[string]string{"app": "x"}}
			originalName := tt.current.Name
			originalLabels := make(map[string]string, len(tt.current.Labels))
			for key, value := range tt.current.Labels {
				originalLabels[key] = value
			}
			originalConditions := append([]Condition(nil), tt.current.Conditions...)

			result, err := Reconcile(blueprint, tt.current)
			if err != nil {
				t.Fatalf("Reconcile() error = %v", err)
			}
			if result.Action != "update" || result.Workload == nil {
				t.Fatalf("result = %+v, want update with workload", result)
			}
			if result.Workload.Name != blueprint.Name || !reflect.DeepEqual(result.Workload.Labels, blueprint.Labels) {
				t.Fatalf("workload = %+v, want blueprint name and labels", result.Workload)
			}
			wantConditions := []Condition{{Type: "Synchronizing", Active: true}}
			if !reflect.DeepEqual(result.Conditions, wantConditions) {
				t.Fatalf("conditions = %+v, want %+v", result.Conditions, wantConditions)
			}
			if tt.current.Name != originalName || !reflect.DeepEqual(tt.current.Labels, originalLabels) || !reflect.DeepEqual(tt.current.Conditions, originalConditions) {
				t.Fatalf("current mutated: %+v", tt.current)
			}

			result.Workload.Labels["app"] = "changed"
			if blueprint.Labels["app"] != "x" {
				t.Fatal("updated workload aliases blueprint labels")
			}
		})
	}
}

func TestReconcileNoneReturnsIsolatedCopies(t *testing.T) {
	blueprint := Blueprint{Name: "desired", Labels: map[string]string{"app": "x"}}
	current := &Workload{
		Name:       "desired",
		Labels:     map[string]string{"app": "x"},
		Conditions: []Condition{{Type: "Ready", Active: true}},
	}

	result, err := Reconcile(blueprint, current)
	if err != nil {
		t.Fatalf("Reconcile() error = %v", err)
	}
	if result.Action != "none" || result.Workload == nil {
		t.Fatalf("result = %+v, want none with workload", result)
	}
	if result.Workload == current {
		t.Fatal("result workload aliases current workload")
	}
	if !reflect.DeepEqual(*result.Workload, *current) {
		t.Fatalf("workload = %+v, want copy of %+v", result.Workload, current)
	}
	if !reflect.DeepEqual(result.Conditions, current.Conditions) {
		t.Fatalf("conditions = %+v, want %+v", result.Conditions, current.Conditions)
	}

	result.Workload.Labels["app"] = "changed"
	result.Workload.Conditions[0].Type = "ChangedWorkloadCondition"
	result.Conditions[0].Type = "ChangedResultCondition"
	if current.Labels["app"] != "x" || current.Conditions[0].Type != "Ready" {
		t.Fatalf("result aliases current: current = %+v", current)
	}
}

func TestReconcileNilAndEmptyLabelsCompareEqual(t *testing.T) {
	tests := []struct {
		name      string
		blueprint Blueprint
		current   *Workload
	}{
		{
			name:      "nil blueprint and empty current",
			blueprint: Blueprint{Name: "x", Labels: nil},
			current:   &Workload{Name: "x", Labels: map[string]string{}},
		},
		{
			name:      "empty blueprint and nil current",
			blueprint: Blueprint{Name: "x", Labels: map[string]string{}},
			current:   &Workload{Name: "x", Labels: nil},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := Reconcile(tt.blueprint, tt.current)
			if err != nil {
				t.Fatalf("Reconcile() error = %v", err)
			}
			if result.Action != "none" || result.Workload == nil {
				t.Fatalf("result = %+v, want none with workload", result)
			}
		})
	}
}

package solution

import "testing"

func TestReviewDifferentEmptyValuedLabelKeysRequireUpdate(t *testing.T) {
	bp := Blueprint{Name: "x", Labels: map[string]string{"desired": ""}}
	current := &Workload{Name: "x", Labels: map[string]string{"existing": ""}}
	got, err := Reconcile(bp, current)
	if err != nil || got.Action != "update" {
		t.Fatalf("different label keys require update; got action=%q err=%v", got.Action, err)
	}
}

